  LinearLayout root, list, topApps, weekBars, overviewCard, historyCard, homeFocusCard, goalCard, focusCard, appsCard, accountCard, accessibilityCard, privateCard, bottomNav; TextView summary, status, accessibilityStatus, cloudStatus, focusStatus, timerFace; ProgressBar goalProgress; SharedPreferences prefs; CloudSync cloud; boolean syncing; int activeTab; CheckBox hardMode; Button focusButton, homeFocusButton; final android.os.Handler timerHandler=new android.os.Handler(android.os.Looper.getMainLooper()); final Runnable timerTick=new Runnable(){public void run(){if(timerFace!=null){long left=prefs.getLong("focusUntil",0)-System.currentTimeMillis();if(left>0){long seconds=(left+999)/1000;timerFace.setText(String.format(Locale.US,"%02d:%02d",seconds/60,seconds%60));homeFocusButton.setText("Focus running · "+duration(left)+" left");}else if("Hard Mode active".contentEquals(focusButton.getText()))refresh();}timerHandler.postDelayed(this,1000);}};
