  @Override public void onCreate(Bundle b){super.onCreate(b);prefs=getSharedPreferences("amythest",0);cloud=new CloudSync(this);render();timerHandler.post(timerTick);if(android.os.Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},7);if(!accessibilityEnabled()&&!prefs.getBoolean("accessibilityExplained",false)){prefs.edit().putBoolean("accessibilityExplained",true).apply();new android.app.AlertDialog.Builder(this).setTitle("Turn on app awareness?").setMessage("Amythest can observe which app is in front and remind you when a distraction reaches your goal. It stores package names on this device, not screen text. Android requires you to turn this on in Accessibility settings.").setNegativeButton("Not now",null).setPositiveButton("Open settings",(dialog,which)->startActivity(new Intent(Settings.ACTION_ACCESSIBILITY_SETTINGS))).show();}}
