  boolean hasAccess(){AppOpsManager ops=(AppOpsManager)getSystemService(APP_OPS_SERVICE);return ops.checkOpNoThrow(AppOpsManager.OPSTR_GET_USAGE_STATS,Process.myUid(),getPackageName())==AppOpsManager.MODE_ALLOWED;}
  boolean accessibilityEnabled(){String enabled=Settings.Secure.getString(getContentResolver(),Settings.Secure.ENABLED_ACCESSIBILITY_SERVICES);if(enabled==null)return false;for(String item:enabled.split(":")){android.content.ComponentName name=android.content.ComponentName.unflattenFromString(item);if(name!=null&&name.getPackageName().equals(getPackageName())&&name.getClassName().equals(AmythestAccessibilityService.class.getName()))return true;}return false;}
