    LinearLayout header=new LinearLayout(this);header.setGravity(android.view.Gravity.CENTER_VERTICAL);ImageView mark=new ImageView(this);mark.setImageResource(getResources().getIdentifier("icon","drawable",getPackageName()));header.addView(mark,new LinearLayout.LayoutParams(dp(34),dp(34)));TextView title=text("amythest",24,true);title.setTextColor(Color.WHITE);title.setPadding(dp(8),0,0,0);header.addView(title);root.addView(header);
